package com.amdocs.telecom.main;
import static spark.Spark.*;import com.fasterxml.jackson.databind.*;import com.amdocs.telecom.util.*;import com.amdocs.telecom.security.*;import com.amdocs.telecom.service.*;import com.amdocs.telecom.scheduler.*;import com.amdocs.telecom.report.*;import com.amdocs.telecom.model.Types.Role;import java.sql.*;import java.util.*;import java.nio.file.*;
public class Application{static final ObjectMapper J=new ObjectMapper();static final AuthService AUTH=new AuthService();static final CaptchaGenerator CAP=new CaptchaGenerator();static final TicketService TICKETS=new TicketService();static final EngineerAssignmentService ASSIGN=new EngineerAssignmentService();static final EscalationService ESC=new EscalationService();static final BackgroundServices BG=new BackgroundServices();static final ReportService REPORTS=new ReportService();
 public static void main(String[]a)throws Exception{DBConnection.getInstance().init();Seeder.seed();port(Integer.parseInt(DBConnection.env("PORT","8080")));staticFiles.location("/static");before("/api/*",(q,r)->r.type("application/json"));exception(Exception.class,(e,q,r)->{r.status(e instanceof SecurityException?401:e instanceof IllegalArgumentException?400:500);r.type("application/json");r.body(json(Collections.singletonMap("error",e.getMessage())));});
 get("/api/health",(q,r)->json(map("status","UP")));
 get("/api/auth/captcha",(q,r)->{String[]c=CAP.create();return json(map("captchaId",c[0],"captcha",c[1]));});
 post("/api/auth/login",(q,r)->{Map<String,Object>b=body(q.body());if(!CAP.verify(str(b,"captchaId"),str(b,"captcha")))throw new SecurityException("Invalid CAPTCHA");AuthService.Challenge c=AUTH.passwordStep(str(b,"username"),str(b,"password"),q.ip());Map<String,Object>m=map("username",c.username,"role",c.role,"message","OTP generated");if("development".equals(DBConnection.env("OTP_MODE","development")))m.put("otp",c.otp);return json(m);});
 post("/api/auth/otp",(q,r)->{Map<String,Object>b=body(q.body());String token=AUTH.otpStep(str(b,"username"),str(b,"otp"));return json(map("token",token));});
 post("/api/auth/logout",(q,r)->{AUTH.logout(token(q));return json(map("message","Logged out"));});
 get("/api/services",(q,r)->{AuthContext x=auth(q);String customer=x.role==Role.CUSTOMER?x.refId:q.queryParams("customerId");return json(query("SELECT service_id,service_code,service_name,service_type,customer_id,activation_date,service_status FROM telecom_services WHERE (? IS NULL OR customer_id=?)",customer,customer));});
 get("/api/tickets",(q,r)->{AuthContext x=auth(q);return json(TICKETS.list(x.role==Role.CUSTOMER?x.refId:null,x.role==Role.NETWORK_ENGINEER?x.refId:null));});
 post("/api/tickets",(q,r)->{AuthContext x=auth(q,Role.CUSTOMER,Role.SERVICE_DESK);Map<String,Object>b=body(q.body());String cust=x.role==Role.CUSTOMER?x.refId:str(b,"customerId");long id=TICKETS.create(cust,str(b,"serviceId"),str(b,"category"),str(b,"description"),str(b,"priority"),str(b,"severity"),x.username);r.status(201);return json(map("ticketId",id));});
 get("/api/tickets/:id/history",(q,r)->{auth(q);return json(TICKETS.history(Long.parseLong(q.params("id"))));});
 put("/api/tickets/:id/status",(q,r)->{AuthContext x=auth(q,Role.SERVICE_DESK,Role.NETWORK_ENGINEER,Role.NETWORK_MANAGER);Map<String,Object>b=body(q.body());TICKETS.status(Long.parseLong(q.params("id")),str(b,"status"),x.username,String.valueOf(b.get("remarks")));return json(map("message","Status updated"));});
 put("/api/tickets/:id/priority",(q,r)->{AuthContext x=auth(q,Role.SERVICE_DESK,Role.NETWORK_MANAGER);Map<String,Object>b=body(q.body());exec("UPDATE trouble_tickets SET priority=?,updated_at=CURRENT_TIMESTAMP WHERE ticket_id=?",str(b,"priority"),Long.parseLong(q.params("id")));return json(map("message","Priority updated"));});
 post("/api/tickets/:id/assign",(q,r)->{AuthContext x=auth(q,Role.SERVICE_DESK,Role.NETWORK_MANAGER);Map<String,Object>b=body(q.body());ASSIGN.assign(Long.parseLong(q.params("id")),str(b,"engineerId"),x.username);return json(map("message","Assigned"));});
 post("/api/tickets/:id/escalate",(q,r)->{AuthContext x=auth(q,Role.SERVICE_DESK,Role.NETWORK_ENGINEER,Role.NETWORK_MANAGER);Map<String,Object>b=body(q.body());ESC.escalate(Long.parseLong(q.params("id")),str(b,"fromLevel"),str(b,"toLevel"),str(b,"reason"),x.username);return json(map("message","Escalated"));});
 post("/api/tickets/:id/resolve",(q,r)->{AuthContext x=auth(q,Role.NETWORK_ENGINEER,Role.NETWORK_MANAGER);Map<String,Object>b=body(q.body());TICKETS.resolve(Long.parseLong(q.params("id")),str(b,"rootCause"),str(b,"resolution"),str(b,"resolutionCode"),x.username);return json(map("message","Resolved"));});
 get("/api/engineers/recommend",(q,r)->{auth(q,Role.SERVICE_DESK,Role.NETWORK_MANAGER);return json(ASSIGN.recommend(q.queryParams("specialization"),q.queryParams("region")));});
 post("/api/events",(q,r)->{auth(q,Role.SERVICE_DESK,Role.NETWORK_MANAGER);Map<String,Object>b=body(q.body());BG.submit(new BackgroundServices.NetworkEvent(str(b,"eventId"),str(b,"networkNode"),str(b,"eventType"),str(b,"severity")));r.status(202);return json(map("message","Queued"));});
 get("/api/notifications",(q,r)->{AuthContext x=auth(q);String id=x.refId==null?x.username:x.refId;return json(query("SELECT notification_id,message,notification_type,created_date,read_status FROM notifications WHERE recipient_id=? ORDER BY created_date DESC",id));});
 post("/api/feedback",(q,r)->{AuthContext x=auth(q,Role.CUSTOMER);Map<String,Object>b=body(q.body());exec("INSERT INTO feedback(ticket_id,customer_id,rating,comments) VALUES(?,?,?,?)",Long.valueOf(str(b,"ticketId")),x.refId,Integer.valueOf(str(b,"rating")),String.valueOf(b.get("comments")));r.status(201);return json(map("message","Feedback submitted"));});
 get("/api/dashboard/manager",(q,r)->{auth(q,Role.NETWORK_MANAGER,Role.SERVICE_DESK);return json(manager());});
 get("/api/reports/:name",(q,r)->{auth(q,Role.SERVICE_DESK,Role.NETWORK_MANAGER);Path p=REPORTS.generate(q.params("name")).get();r.type("text/csv");r.header("Content-Disposition","attachment; filename=\""+p.getFileName()+"\"");return new String(Files.readAllBytes(p),"UTF-8");});BG.start();awaitInitialization();System.out.println("TSATMS running on http://localhost:"+port());}
 static AuthContext auth(spark.Request q,Role...roles){AuthContext x=AUTH.get(token(q));if(x==null)throw new SecurityException("Authentication required");if(roles.length>0&&!Arrays.asList(roles).contains(x.role))throw new SecurityException("Forbidden for role "+x.role);return x;}static String token(spark.Request q){String h=q.headers("Authorization");return h!=null&&h.startsWith("Bearer ")?h.substring(7):"";}static Map<String,Object>body(String s)throws Exception{return J.readValue(s,Map.class);}static String str(Map<String,Object>b,String k){Object v=b.get(k);if(v==null||String.valueOf(v).trim().isEmpty())throw new IllegalArgumentException(k+" is required");return String.valueOf(v);}static String json(Object o){try{return J.writeValueAsString(o);}catch(Exception e){throw new RuntimeException(e);}}static Map<String,Object>map(Object...x){Map<String,Object>m=new LinkedHashMap<>();for(int i=0;i<x.length;i+=2)m.put(String.valueOf(x[i]),x[i+1]);return m;}static List<Map<String,Object>>query(String sql,Object...v)throws SQLException{List<Map<String,Object>>a=new ArrayList<>();try(Connection c=DBConnection.getInstance().get();PreparedStatement p=c.prepareStatement(sql)){for(int i=0;i<v.length;i++)p.setObject(i+1,v[i]);try(ResultSet r=p.executeQuery()){ResultSetMetaData md=r.getMetaData();while(r.next()){Map<String,Object>m=new LinkedHashMap<>();for(int i=1;i<=md.getColumnCount();i++)m.put(md.getColumnLabel(i),r.getObject(i));a.add(m);}}}return a;}static void exec(String sql,Object...v)throws SQLException{try(Connection c=DBConnection.getInstance().get();PreparedStatement p=c.prepareStatement(sql)){for(int i=0;i<v.length;i++)p.setObject(i+1,v[i]);p.executeUpdate();}}static Map<String,Object>manager()throws SQLException{Map<String,Object>m=new LinkedHashMap<>();try(Connection c=DBConnection.getInstance().get();Statement s=c.createStatement();ResultSet r=s.executeQuery("SELECT COUNT(*) total,SUM(CASE WHEN status NOT IN('RESOLVED','CLOSED','CANCELLED') THEN 1 ELSE 0 END) open_count,SUM(CASE WHEN priority='CRITICAL' AND status NOT IN('CLOSED','CANCELLED') THEN 1 ELSE 0 END) critical,SUM(CASE WHEN CURRENT_TIMESTAMP>sla_deadline AND status NOT IN('RESOLVED','CLOSED','CANCELLED') THEN 1 ELSE 0 END) breached,SUM(CASE WHEN resolution_date>=CURRENT_DATE THEN 1 ELSE 0 END) resolved_today,AVG(CASE WHEN resolution_date IS NOT NULL THEN DATEDIFF('MINUTE',created_date,resolution_date)/60.0 END) avg_hours FROM trouble_tickets")){r.next();m.put("totalOpenTickets",r.getInt("open_count"));m.put("criticalIncidents",r.getInt("critical"));m.put("slaBreached",r.getInt("breached"));m.put("resolvedToday",r.getInt("resolved_today"));m.put("averageResolutionTimeHours",r.getObject("avg_hours"));}try(Connection c=DBConnection.getInstance().get();Statement s=c.createStatement();ResultSet r=s.executeQuery("SELECT COUNT(*) FROM v_ticket_sla WHERE sla_status='AT_RISK'")){r.next();m.put("slaAtRisk",r.getInt(1));}return m;}}
